import{_ as e,o as r,c as s,a3 as o}from"./chunks/framework.CZBGEXos.js";const p=JSON.parse('{"title":"Primeros pasos","description":"","frontmatter":{},"headers":[],"relativePath":"guia-inicio/primeros-pasos.md","filePath":"guia-inicio/primeros-pasos.md"}'),i={name:"guia-inicio/primeros-pasos.md"};function t(n,a,l,d,c,u){return r(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="primeros-pasos" tabindex="-1">Primeros pasos <a class="header-anchor" href="#primeros-pasos" aria-label="Permalink to &quot;Primeros pasos&quot;">​</a></h1><p>Este es el recorrido típico para poner una obra en marcha y empezar a operar. Síguelo en orden la primera vez; después podrás moverte libremente entre los módulos.</p><h2 id="_1-iniciar-sesion" tabindex="-1">1. Iniciar sesión <a class="header-anchor" href="#_1-iniciar-sesion" aria-label="Permalink to &quot;1. Iniciar sesión&quot;">​</a></h2><p>Ingresa con tu <strong>RUT y contraseña</strong>. Si es tu primer ingreso, crea tu contraseña definitiva y define tu <strong>PIN de firma</strong>. Ver <a href="/manual/guia-inicio/instalacion.html">Cómo ingresar</a>.</p><h2 id="_2-revisar-tu-empresa" tabindex="-1">2. Revisar tu empresa <a class="header-anchor" href="#_2-revisar-tu-empresa" aria-label="Permalink to &quot;2. Revisar tu empresa&quot;">​</a></h2><p>Si eres administrador, entra a <strong>Mi Empresa</strong> y revisa:</p><ul><li>Los <strong>datos</strong> de la empresa (razón social, logo, color).</li><li>Los <strong>roles</strong> que usarás para tu equipo.</li><li>El catálogo de <strong>cargos</strong> (oficios de obra).</li></ul><p>Ver <a href="/manual/modulos/tenants.html">Mi Empresa</a>.</p><h2 id="_3-registrar-a-las-personas" tabindex="-1">3. Registrar a las personas <a class="header-anchor" href="#_3-registrar-a-las-personas" aria-label="Permalink to &quot;3. Registrar a las personas&quot;">​</a></h2><p>Da de alta a las personas de tu empresa (prevencionista, supervisores, trabajadores). Para cada una define su <strong>rol</strong> (qué puede hacer) y su <strong>cargo</strong> (su oficio en obra), y a qué <strong>obras</strong> se asigna.</p><p>Ver <a href="/manual/modulos/personas.html">Personas</a>.</p><h2 id="_4-crear-tu-primera-obra" tabindex="-1">4. Crear tu primera obra <a class="header-anchor" href="#_4-crear-tu-primera-obra" aria-label="Permalink to &quot;4. Crear tu primera obra&quot;">​</a></h2><p>Crea la obra. Al guardarla, la plataforma <strong>prepara automáticamente los documentos obligatorios</strong> del DS 44 según las características que marcaste. No tienes que crearlos uno por uno.</p><p>Ver <a href="/manual/modulos/obras.html">Obras</a>.</p><h2 id="_5-cargar-y-firmar-documentos" tabindex="-1">5. Cargar y firmar documentos <a class="header-anchor" href="#_5-cargar-y-firmar-documentos" aria-label="Permalink to &quot;5. Cargar y firmar documentos&quot;">​</a></h2><ul><li>Sube los archivos a los documentos obligatorios de la obra.</li><li>Asigna los documentos a las personas que correspondan.</li><li>Cada persona recibe el aviso y <strong>firma con su PIN</strong>.</li></ul><p>Ver <a href="/manual/modulos/documentos.html">Documentos</a> y <a href="/manual/modulos/firmas.html">Firmas Digitales</a>.</p><h2 id="_6-programar-actividades" tabindex="-1">6. Programar actividades <a class="header-anchor" href="#_6-programar-actividades" aria-label="Permalink to &quot;6. Programar actividades&quot;">​</a></h2><p>Programa las charlas y capacitaciones, y registra la <strong>asistencia firmada</strong> de los trabajadores y del relator.</p><p>Ver <a href="/manual/modulos/actividades.html">Actividades</a>.</p><h2 id="_7-hacer-seguimiento-desde-el-dashboard" tabindex="-1">7. Hacer seguimiento desde el Dashboard <a class="header-anchor" href="#_7-hacer-seguimiento-desde-el-dashboard" aria-label="Permalink to &quot;7. Hacer seguimiento desde el Dashboard&quot;">​</a></h2><p>Revisa tus pendientes, el avance del cumplimiento y los incidentes recientes desde el <a href="/manual/modulos/dashboard.html">Dashboard</a>.</p><h2 id="flujo-resumido" tabindex="-1">Flujo resumido <a class="header-anchor" href="#flujo-resumido" aria-label="Permalink to &quot;Flujo resumido&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Iniciar sesión → Revisar empresa → Registrar personas → Crear obra</span></span>
<span class="line"><span>   → Cargar y firmar documentos → Programar actividades → Hacer seguimiento</span></span></code></pre></div><blockquote><p>💡 <strong>Avance del cumplimiento:</strong> cuando completes lo que pide cada fase de la obra (Planificar → Hacer → Verificar → Actuar), podrás avanzar a la siguiente. La plataforma verifica que no queden pendientes obligatorios antes de dejarte avanzar. Ver <a href="/manual/modulos/obras.html">Obras</a>.</p></blockquote>`,25)])])}const h=e(i,[["render",t]]);export{p as __pageData,h as default};
